    )

    fun `queueInsert`(
        `uri`: kotlin.String,
        `next`: kotlin.Boolean,
        `sink`: AmActionSink,
    )

    fun `command`(
        `cmd`: AmPlayerCommand,
        `sink`: AmActionSink,
    )

    fun `library`(
        `scope`: AmLibraryScope,
        `limit`: kotlin.UInt,
        `offset`: kotlin.UInt,
        `sink`: AmPageSink,
    )

    fun `recommendations`(`sink`: AmShelvesSink)

    fun `resolve`(
        `uri`: kotlin.String,
        `sink`: AmItemSink,
    )

    fun `search`(
        `query`: kotlin.String,
        `limit`: kotlin.UInt,
        `sink`: AmSearchSink,
    )

    fun `isFavorite`(
        `uris`: List<kotlin.String>,
        `sink`: AmFavoritesSink,
    )

    fun `addFavorite`(
        `uri`: kotlin.String,
        `sink`: AmActionSink,
    )

    companion object
}

