    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(
        private val handle: Long,
    ) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_bridgething_companion_fn_free_connectivityinbox(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object")
        }
        return uniffiRustCall { status ->
            UniffiLib.uniffi_bridgething_companion_fn_clone_connectivityinbox(handle, status)
        }
    }

    override fun `onChanged`(`online`: kotlin.Boolean) =
        callWithHandle {
            uniffiRustCall { _status ->
                UniffiLib.uniffi_bridgething_companion_fn_method_connectivityinbox_on_changed(
                    it,
                    FfiConverterBoolean.lower(`online`),
                    _status,
                )
            }
        }

    /**
     * @suppress
     */
    companion object
}

