public object FfiConverterTypeWsTransport : FfiConverter<WsTransport, Long> {
    internal val handleMap = UniffiHandleMap<WsTransport>()

    override fun lower(value: WsTransport): Long {
        if (value is WsTransportImpl) {
            // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
        } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
        }
    }

    override fun lift(value: Long): WsTransport {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return WsTransportImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): WsTransport = lift(buf.getLong())

    override fun allocationSize(value: WsTransport) = 8UL

    override fun write(
        value: WsTransport,
        buf: ByteBuffer,
    ) {
        buf.putLong(lower(value))
    }
}

